ValidationRule.errorConditionFormula:
AND(
    NOT($User.BypassValidationRules__c),
    NOT(ISNEW()),
    ISCHANGED(ApprovalStatus__c),
    NOT(
        OR(
            /* Draft -> Pending Approval */
            AND(
                ISPICKVAL(PRIORVALUE(ApprovalStatus__c), "Draft"),
                ISPICKVAL(ApprovalStatus__c, "Pending Approval")
            ),

												/* Pending Approval -> Draft */
            AND(
                ISPICKVAL(PRIORVALUE(ApprovalStatus__c), "Pending Approval"),
                ISPICKVAL(ApprovalStatus__c, "Draft")
            ),

            /* Pending Approval -> Approved */
            AND(
                ISPICKVAL(PRIORVALUE(ApprovalStatus__c), "Pending Approval"),
                ISPICKVAL(ApprovalStatus__c, "Approved")
            ),

            /* Pending Approval -> Rejected */
            AND(
                ISPICKVAL(PRIORVALUE(ApprovalStatus__c), "Pending Approval"),
                ISPICKVAL(ApprovalStatus__c, "Rejected")
            ),

            /* Rejected -> Draft */
            AND(
                ISPICKVAL(PRIORVALUE(ApprovalStatus__c), "Rejected"),
                ISPICKVAL(ApprovalStatus__c, "Draft")
            )
        )
    )
)
